    """Coerce a legacy numeric value, treating empty or missing values as zero."""
    if value is None or value == "":
        return Decimal("0")
    return Decimal(str(value))


def _live_account_credit_hold(record, tables):
    """Return the first live account's CRED_HOLD value, or an empty string."""
    account_id = record.get("ACCT_ID", "")
    for row in tables.get("ACCT_MASTER", []):
        if row.get("DEL_FLG", "") != "Y" and row.get("ACCT_ID", "") == account_id:
            return row.get("CRED_HOLD", "")
    return ""


def fire(state: str, event: str, record: dict, tables: dict) -> dict:
