        return {
            "state": "X",
            "record": new_record,
            "audits": ["ORD_CANC"],
            "notifies": [],
            "matched": True,
        }

    if state == "A" and event == "cancel":
        if _live_account_credit_hold(record, tables) != "Y":
            return {
                "state": "X",
                "record": new_record,
                "audits": ["ORD_CANC"],
                "notifies": [],
                "matched": True,
            }

    if state == "I" and event == "cancel":
        return {
            "state": "X",
            "record": new_record,
            "audits": ["ORD_CANC_INV"],
            "notifies": ["credit_note"],
            "matched": True,
        }

    return {
        "state": state,
        "record": new_record,
        "audits": ["WF_NOMATCH"],
        "notifies": [],
        "matched": False,
    }
